import json
import pandas as pd
import pyarrow as pa
import pyarrow.parquet as pq
from datetime import datetime

field_map = {
    'user_id':      {'source_a': 'id',              'source_b': 'user_id',      'source_c': 'userId'},
    'name':         {'source_a': 'full_name',       'source_b': 'name',         'source_c': 'userName'},
    'email':        {'source_a': 'email',           'source_b': 'email_address','source_c': 'email'},
    'created_date': {'source_a': 'registration_date','source_b': 'created_at',  'source_c': 'joined'},
    'status':       {'source_a': 'status',          'source_b': 'is_active',    'source_c': 'active'},
}

def norm_date(v):
    if v is None: return None
    s = str(v).strip()
    for fmt in ['%Y-%m-%d', '%Y-%m-%d %H:%M:%S', '%Y/%m/%d', '%m/%d/%Y', '%d-%m-%Y']:
        try: return datetime.strptime(s, fmt).strftime('%Y-%m-%d')
        except ValueError: pass
    return s

def norm_status(v):
    if v is None: return None
    if isinstance(v, bool): return 'active' if v else 'inactive'
    s = str(v).strip().lower()
    if s in ('true','1','yes'): return 'active'
    if s in ('false','0','no'): return 'inactive'
    return str(v)

def norm_str(v):
    return str(v) if v is not None else None

converters = {
    'user_id': lambda v: int(v),
    'created_date': norm_date,
    'status': norm_status,
    'name': norm_str,
    'email': norm_str,
}

SOURCES = ['source_a','source_b','source_c']
FIELDS = ['user_id','name','email','created_date','status']

def load():
    data = {}
    with open('/data/source_a/users.json') as f:
        a_rows = json.load(f)
    data['source_a'] = {r['id']: {uf: converters[uf](r[sf]) for uf,sf in [(k, m['source_a']) for k,m in field_map.items()]} for r in a_rows}

    b_df = pd.read_csv('/data/source_b/users.csv')
    data['source_b'] = {}
    for _, row in b_df.iterrows():
        rd = row.to_dict()
        rec = {uf: converters[uf](rd[m['source_b']]) for uf,m in field_map.items() if rd.get(m['source_b']) is not None and not pd.isna(rd.get(m['source_b']))}
        data['source_b'][rec['user_id']] = rec

    c_df = pd.read_parquet('/data/source_c/users.parquet')
    data['source_c'] = {}
    for _, row in c_df.iterrows():
        rd = row.to_dict()
        rec = {uf: converters[uf](rd[m['source_c']]) for uf,m in field_map.items() if rd.get(m['source_c']) is not None and not pd.isna(rd.get(m['source_c']))}
        data['source_c'][rec['user_id']] = rec
    return data

def main():
    data = load()
    all_users = set()
    for s in SOURCES: all_users.update(data[s].keys())

    merged = []
    conflicts = []
    for uid in sorted(all_users):
        recs = {s: data[s].get(uid) for s in SOURCES}
        mrec = {}
        for f in FIELDS:
            sel = None
            for s in SOURCES:
                if recs[s] is not None and f in recs[s]:
                    sel = recs[s][f]; break
            mrec[f] = sel
        for f in FIELDS:
            present = {s: recs[s][f] for s in SOURCES if recs[s] is not None and f in recs[s]}
            if len(present) > 1 and len(set(map(repr, present.values()))) > 1:
                sel = next(present[s] for s in SOURCES if s in present)
                conflicts.append({'user_id': uid, 'field': f,
                                   'values': {s: present[s] for s in SOURCES if s in present},
                                   'selected': sel})
        merged.append(mrec)

    df = pd.DataFrame(merged)[FIELDS]
    df['user_id'] = df['user_id'].astype(int)
    for c in ['name','email','created_date','status']:
        df[c] = df[c].astype(object)
    table = pa.Table.from_pandas(df, schema=pa.schema([
        ('user_id', pa.int64()), ('name', pa.string()), ('email', pa.string()),
        ('created_date', pa.string()), ('status', pa.string())]))
    pq.write_table(table, '/app/merged_users.parquet')

    report = {'total_conflicts': len(conflicts), 'conflicts': conflicts}
    with open('/app/conflicts.json','w') as f:
        json.dump(report, f, indent=2)

    print(df.to_string())
    print(json.dumps(report, indent=2))

if __name__ == '__main__':
    main()
PYEOF
